class StructuralValidator {
    constructor(payload) {
        this.payload = { ...payload };
        this.warnings = [];
        this.fatalErrors = [];
    }

    runAllInspections() {
        this.validateLayoutHarmony();
        this.validateBloggerRules();
        this.validateCLSRisk();
        this.validateMobileReadability();
        return {
            isValid: this.fatalErrors.length === 0,
            payload: this.payload,
            errors: this.fatalErrors,
            warnings: this.warnings
        };
    }

    validateLayoutHarmony() {
        const { gridLayout, sidebarPosition } = this.payload;
        if (gridLayout === 'mural' && sidebarPosition !== 'none') {
            this.warnings.push('[UI FIX] Grid Mural exige largura total. Sidebar desativada automaticamente.');
            this.payload.sidebarPosition = 'none';
        }
        if (gridLayout === 'quadrado' && this.payload.columns === 1) {
            this.payload.gridLayout = 'lista';
            this.warnings.push('[UI FIX] Grid quadrado não suporta formato lista. Alterado para lista clássica.');
        }
    }

    validateBloggerRules() {
        const { commentSystem, postModules } = this.payload;
        if (commentSystem !== 'blogger-native') {
            this.warnings.push('[ENGINE FIX] Sistema de comentários forçado para blogger-native devido a restrições de CSP.');
            this.payload.commentSystem = 'blogger-native';
        }
        if (postModules && postModules.includes('related-posts')) {
            this.payload._requiresVanillaJS = true;
        }
    }

    validateCLSRisk() {
        const { headerStyle, heroSection, adSlots } = this.payload;
        if (headerStyle === 'transparent-scroll' && heroSection === 'static-banner') {
            this.warnings.push('[SEO FIX] Risco de legibilidade/CLS com Header transparente sobre Banner sólido. Header fixado.');
            this.payload.headerStyle = 'sticky';
        }
        if (adSlots === true) {
            this.warnings.push('[SEO SIGNAL] Injetar min-height nos slots do AdSense para evitar Layout Shift.');
            this.payload._injectAdSenseMinHeight = true;
        }
    }

    validateMobileReadability() {
        const { menuType, typography } = this.payload;
        if (menuType === 'mega-menu' && ['playfair', 'roboto-slab'].includes(typography)) {
            this.payload._forceMobileMenuSansSerif = true;
            this.warnings.push('[UX FIX] Fonte serifada detetada em Mega Menu. Mobile fallback ativado para Inter.');
        }
        if (menuType === 'simple' && this.payload.sidebarPosition === 'none') {
            this.payload.menuType = 'offcanvas';
            this.warnings.push('[UX FIX] Layout sem sidebar. Offcanvas ativado obrigatoriamente para navegação mobile.');
        }
    }
}

module.exports = StructuralValidator;
